/**
 * @file
 * @brief ztest public APIs
 */

#ifndef ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_
#define ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_

#include <zephyr/kernel.h>
#include <zephyr/sys/util.h>
#include <zephyr/ztest.h>

#ifdef __cplusplus
extern "C" {
#endif

/**
 * @brief Test case structure
 *
 * @details This structure is used to define a test case.
 */
struct ztest_test_case {
	/** Name of the test case */
	const char *test_name;
	/** Function pointer to the test case */
	void (*test_fn)(void);
	/** Name of the test suite */	
	const char *suite_name;
};

/**
 * @brief Test suite structure
 *
 * @details This structure is used to define a test suite.
 */
struct ztest_test_suite {
	/** Name of the test suite */
	const char *suite_name;
	/** Array of test cases in the suite */
	const struct ztest_test_case *test_cases;
	/** Number of test cases in the suite */
	size_test_cases;
	/** Setup function for the test suite */
	void (*suite_setup)(void);
	/** Teardown function for the test suite */
	void (*suite_teardown)(void);
	/** Setup function for each test case */
	void (*test_setup)(void);
	/** Teardown function for each test case */	
	void (*test_teardown)(void);
};

/**
 * @brief Declare a test case
 *
 * @details This macro declares a test case function and registers it
 *          within the specified test suite.
 *
 * @param suite_name The name of the test suite.
 * @param test_name The name of the test case.
 */
#define ZTEST_TEST_CASE(suite_name, test_name) \
	static void test_name(void); \
	ZTEST_DMEM static const struct ztest_test_case __used \
		_CONCAT(ztest_test_case_, test_name) = { \
		.test_name = #test_name, \
		.test_fn = test_name, \
		.suite_name = #suite_name, \
	}; /* FIX: Added missing semicolon */ \
	static void test_name(void)

/**
 * @brief Declare a test suite
 *
 * @details This macro declares a test suite and registers it.
 *
 * @param suite_name The name of the test suite.
 * @param ... A list of test cases (e.g., test_case_1, test_case_2).
 */
#define ZTEST_TEST_SUITE(suite_name, ...) \
	extern const struct ztest_test_case _CONCAT(ztest_test_case_, __VA_ARGS__); \
	static const struct ztest_test_case *const _CONCAT(suite_name, _cases)[] = { \
		FOR_EACH_FIXED_ARG(ZTEST_TEST_CASE_PTR, __VA_ARGS__) \
	}; \
	ZTEST_DMEM static const struct ztest_test_suite __used \
		_CONCAT(ztest_test_suite_, suite_name) = { \
		.suite_name = #suite_name, \
		.test_cases = _CONCAT(suite_name, _cases), \
		.num_test_cases = ARRAY_SIZE(_CONCAT(suite_name, _cases)), \
		.suite_setup = NULL, \
		.suite_teardown = NULL, \
		.test_setup = NULL, \
		.test_teardown = NULL, \
	}; \
	static inline void _CONCAT(suite_name, _setup)(void) {} \
	static inline void _CONCAT(suite_name, _teardown)(void) {} \
	static inline void _CONCAT(suite_name, _test_setup)(void) {} \
	static inline void _CONCAT(suite_name, _test_teardown)(void) {}

/**
 * @brief Declare a test suite with setup and teardown functions
 *
 * @details This macro declares a test suite with custom setup and teardown
 *          functions for the suite and individual test cases.
 *
 * @param suite_name The name of the test suite.
 * @param suite_setup_fn Function to call before the suite runs.
 * @param suite_teardown_fn Function to call after the suite runs.
 * @param test_setup_fn Function to call before each test case.
 * @param test_teardown_fn Function to call after each test case.
 * @param ... A list of test cases (e.g., test_case_1, test_case_2).
 */
#define ZTEST_TEST_SUITE_WITH_SETUP(suite_name, suite_setup_fn, suite_teardown_fn, \
				    test_setup_fn, test_teardown_fn, ...) \
	extern const struct ztest_test_case _CONCAT(ztest_test_case_, __VA_ARGS__); \
	static const struct ztest_test_case *const _CONCAT(suite_name, _cases)[] = { \
		FOR_EACH_FIXED_ARG(ZTEST_TEST_CASE_PTR, __VA_ARGS__) \
	}; \
	ZTEST_DMEM static const struct ztest_test_suite __used \
		_CONCAT(ztest_test_suite_, suite_name) = { \
		.suite_name = #suite_name, \
		.test_cases = _CONCAT(suite_name, _cases), \
		.num_test_cases = ARRAY_SIZE(_CONCAT(suite_name, _cases)), \
		.suite_setup = suite_setup_fn, \
		.suite_teardown = suite_teardown_fn, \
		.test_setup = test_setup_fn, \
		.test_teardown = test_teardown_fn, \
	}; \
	static inline void _CONCAT(suite_name, _setup)(void) {} \
	static inline void _CONCAT(suite_name, _teardown)(void) {} \
	static inline void _CONCAT(suite_name, _test_setup)(void) {} \
	static inline void _CONCAT(suite_name, _test_teardown)(void) {}

/* Helper macro for ZTEST_TEST_SUITE */
#define ZTEST_TEST_CASE_PTR(test_name) \
	&_CONCAT(ztest_test_case_, test_name)

/* Helper macro for ZTEST_TEST_SUITE */
#define ZTEST_DMEM __attribute__((section(".ztest_data")))

#ifdef __cplusplus
}
#endif

#endif /* ZEPHYR_INCLUDE_ZTEST_ZTEST_TEST_H_ */
